// ============================================================
// VALIDATE INPUT — attribute_id is required
// ============================================================
const items = $input.all();
const query = items[0]?.json?.query || items[0]?.json?.body || items[0]?.json || {};

const attributeId = parseInt(query.attribute_id);

if (!attributeId || isNaN(attributeId) || attributeId <= 0) {
  return [{
    json: {
      _valid: false,
      _error: {
        success: false,
        message: 'attribute_id query parameter is required and must be a positive integer.'
      }
    }
  }];
}

return [{
  json: {
    _valid: true,
    attributeId: attributeId
  }
}];

// ============================================================
// FORMAT ATTRIBUTE TERMS RESPONSE
// ============================================================
const inputItems = $input.all();
const attributeId = $('Code - Validate Input').first().json.attributeId;

try {
  let rawData = inputItems[0]?.json;
  let terms = [];

  // Check for WooCommerce error response
  if (rawData && rawData.code) {
    return [{
      json: {
        success: false,
        message: rawData.message || 'Failed to fetch attribute terms.',
        terms: []
      }
    }];
  }

  if (Array.isArray(rawData)) {
    terms = rawData;
  } else if (inputItems.length > 1 || (rawData && rawData.id)) {
    // n8n splits array responses into separate items
    terms = inputItems.map(item => item.json);
  }

  // Map to clean format
  const cleanTerms = terms
    .filter(term => term && term.id)
    .map(term => ({
      id: term.id,
      name: term.name || '',
      slug: term.slug || '',
      description: term.description || '',
      count: term.count || 0
    }));

  return [{
    json: {
      success: true,
      attribute_id: attributeId,
      terms: cleanTerms
    }
  }];
} catch (error) {
  return [{
    json: {
      success: false,
      message: 'Failed to fetch attribute terms: ' + error.message,
      terms: []
    }
  }];
}

// Pass through the validation error as the response
const items = $input.all();
return [{ json: items[0].json._error }];
